param([Parameter(Mandatory=$true)][string]$CheckRoot)
$ErrorActionPreference='Stop'
$taskProject=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$taskJar="$taskProject/build/libs/WitherSkyRU-26.1.2-fabric-0.15.70-dev.jar";$taskHash=(Get-FileHash -LiteralPath $taskJar).Hash
$taskScope=Get-Content "$CheckRoot/CHECK_SCOPE.json" -Raw|ConvertFrom-Json
$taskAudit=Get-Content "$taskProject/translation-source/NPC_AUDIT_0.15.70.json" -Raw|ConvertFrom-Json
$taskProof=Get-Content "$taskProject/translation-source/JAR_SCOPE_0.15.70.json" -Raw|ConvertFrom-Json
$taskPerf=Get-Content "$taskProject/translation-source/PERFORMANCE_0.15.70_RAW.json" -Raw|ConvertFrom-Json
if($taskScope.targeted_only -or $taskScope.tests_passed.Count -ne 121 -or @($taskScope.tests_passed|Sort-Object -Unique).Count -ne 121 -or $taskScope.runtime_jar_sha256 -ne $taskHash -or $taskAudit.jar_sha256 -ne $taskHash -or $taskProof.jar_sha256 -ne $taskHash -or $taskPerf.jar_sha256 -ne $taskHash){throw 'Incomplete/different executable evidence'}
if($taskAudit.catalogue_changed_record_ids.Count -ne 0 -or $taskAudit.after_unchanged -ne 0 -or (Get-Content "$CheckRoot/TestNpc70-output.txt" -Raw) -notmatch '149552 assertions'){throw 'Incomplete independent tests'}
$taskFlags=@($taskPerf.results|Where-Object {$_.cpu_percent[0] -gt 10 -and $_.cpu_percent[1] -gt 10})
$taskLines=@('# WitherSkyRU 0.15.70-dev — продолжения NPC','', 'Дата: 2026-10-15. Minecraft 26.1.2 / Fabric.','', '## Что добавлено','', '22 точные реплики для 15 NPC, все с независимым сохранённым исходным текстом из игровых записей. Две формы ответа Максвелла на изучение силы поддерживают имя игрока, включая совпадения имён с переводимыми словами. Эти две формы подтверждены опубликованным текстом, а не живым пакетом пользователя.','', 'Кэт: две формы сообщения о времени — «питомца можно забрать через…» и «возвращайся через…». Дни, часы, минуты и секунды переводятся без пересчёта значений. Формы поддерживают разные значения и счётчик повторов. Старая работающая форма минут и секунд сохранена; это не сертификат всех возможных форм таймера сервера.','', 'Джейкоб: личный рекорд соревнования, категория и награда за участие. Поддержаны десять закрытых названий культур и пять известных категорий. У старой строки «You collected…» исправлена граница цветного пробела и надписи PERSONAL BEST: число не заменяется и не перекрашивается. Исправлен один старый точный результат BRONZE для моркови. Слово категории теперь русское.','', '## Точные реплики этой партии','', '| Персонаж | Новых точных реплик |','|---|---:|')
foreach($taskRow in $taskAudit.batch){$taskLines+="| $($taskRow.speaker) | $($taskRow.new_exact_lines) |"}
$taskLines+=@('','Динамические формы Максвелла, Кэт и Джейкоба не считаются тысячами новых строк за счёт подстановки чисел. Одна исправленная старая запись BRONZE также не включена в 22 новых. Два запроса Duke/Rusty пока точные — для наблюдавшейся зачарованной золотой моркови, не для всех возможных товаров.','', '## Проверка наблюдений','', '| Набор из 143 отобранных сообщений NPC | Версия 69 | Версия 70 |','|---|---:|---:|','| Без изменения видимого текста | 39 | 0 |','| С изменением видимого текста | 104 | 143 |','', 'Это конечный набор английских NPC-сообщений из записей 9–14 октября, не все реплики сервера. Изменение строки само по себе не доказывает полный качественный перевод. Все 39 прежних пропусков дополнительно проверены отдельными ожидаемыми результатами: 22 точных текста и 17 числовых примеров. Существующие уже поддержанные числовые варианты также перепроверены.','', 'Полный объём оставшихся реплик Hypixel неизвестен: общая цифра «не переведено на сервере» не выдумывается. Полные ветки Enchantment Nerd, неполученные современные диалоги Абифона, произвольные варианты поручений и все сюжетные ветви остальных NPC не объявляются готовыми. Имена NPC в префиксе сохраняются.','', '## Качество и безопасность','', '121 отдельная группа проверок прошла на одном финальном JAR. Семь целевых успешных процессов перенесены с тем же SHA256; остальные 114 выполнены в полном прогоне. Новый независимый тест — 149 552 утверждения. Сохраняются цвета, жирность, текущие hover/click/insertion, числовые символы, имена и головы игроков. Обычный пользовательский чат, подписанные и клиентские сообщения защищены; команды не выполняются.','', 'В дифференциальном тесте со старой версией 60 исключена ровно одна намеренно исправленная строка BRONZE; её новая цель отдельно проверяется TestNpc70 и старыми 15 сохранёнными цветными образцами pass10. Остальные прежние точные записи сравниваются со старым результатом. Старые снимки исходного английского текста не переписывались.','', 'Все 8 937 карточек предметов сравнены с версией 69: полный результат совпадает. Это защита от побочных изменений, не заявление о готовности старых проблемных описаний.','', '## Оптимизация','', 'Точные реплики объединяются с существующим индексом при запуске. Новые грамматики проверяются только для закрытых NPC при поступлении/обновлении чата, а не в каждом кадре. Новых перехватов кадров, кэшей, удержания Style/Component между кадрами или сетевых обращений нет.','', 'Все классы обработки кадров, мировых надписей, HUD, F3, предметов, словаря и кэшей побайтно совпадают с версией 69. Это подтверждено сравнением всех JAR-записей в JAR_SCOPE_0.15.70.json. Оптимизация контекста версии 67 сохранена.','', 'Проверка обработки сообщений: 20 отдельных процессов, порядок 69 → 70 → 70 → 69 для каждого из пяти сценариев. Прогрев 20 000 пакетов; четыре раунда по 4 000 пакетов, по десять строк в пакете. Сохранены все раунды времени и выделения памяти. Это замеры текстового API, не шрифтов, мира, GPU или игрового FPS.','', '| Сценарий | Изменение времени, два порядка | Версия 70, мкс на сообщение |','|---|---:|---:|')
$taskCulture=[Globalization.CultureInfo]::InvariantCulture
function Fmt70($n){return ([double]$n).ToString('0.000',$taskCulture)}
foreach($taskRow in $taskPerf.results){$taskLines+="| $($taskRow.mode) | $(Fmt70 $taskRow.cpu_percent[0])% / $(Fmt70 $taskRow.cpu_percent[1])% | $(Fmt70 $taskRow.after_microseconds_per_input[0]) / $(Fmt70 $taskRow.after_microseconds_per_input[1]) |"}
$taskLines+=@('','unknown/existing сравнивают одинаковый полезный результат. named/duration/contest выполняют дополнительный перевод, которого раньше не было, поэтому большая стоимость этих строк не является сравнением одинаковой работы.', '', "Сценариев с увеличением времени больше 10% в обоих порядках: $($taskFlags.Count). Результаты не отбрасывались; все числа и раунды — PERFORMANCE_0.15.70_RAW.json.",'', 'Игровой FPS версии 70 ещё не измерен. Нулевое влияние на FPS не доказано. Установленная игра не изменялась, не запускалась и не перезапускалась.','', '## Источники','', '- NPC_GAPS_OBSERVED_0.15.60.json — ранее отобранные публичные строки NPC. Хеш исходного снимка и отдельная копия входов — NPC_OBSERVED_0.15.70.json. Полные журналы, пользовательский чат и личные ответы форм не включены.','- NPC_0.15.70_REVIEWED.tsv — вычитанные цели точных реплик, отдельно от игровых исходников.','- [Maxwell: две опубликованные формы с именем игрока](https://hypixel-skyblock.fandom.com/wiki/Maxwell). Они не выданы за новые наблюдавшиеся пакеты.','', '## Файл','', "JAR: $([IO.Path]::GetFileName($taskJar))", "Размер: $((Get-Item -LiteralPath $taskJar).Length) байт.", "SHA256: $taskHash")
$taskReuseCount=$taskScope.reused_same_executable_successes.Count
$taskLines=@($taskLines|ForEach-Object {$_.Replace('поэтому большая стоимость этих строк не является сравнением одинаковой работы.','это сравнение разных объёмов полезной работы, не изменение игрового FPS.')})
$taskLines=@($taskLines|ForEach-Object {$_.Replace('Семь целевых успешных процессов перенесены с тем же SHA256; остальные 114 выполнены в полном прогоне.',"$taskReuseCount целевых успешных процессов перенесены с тем же SHA256; остальные $(121-$taskReuseCount) выполнены в полном прогоне.")})
$taskLines+=@('','## Сохранение прежних веток','', 'Общее правило награды за участие уступает существующему точному диалогу Сада для моркови. Это пересечение обнаружено проверкой TestGreenhouseTutorial; финальный JAR сохраняет прежний текст и семантические цвета этой реплики. Предварительная сборка 6D79CBDF отклонена и хранится только в build/prototypes, не в поставляемых файлах.')
[IO.File]::WriteAllText("$taskProject/translation-source/NPC_0.15.70_RU.md",($taskLines -join "`n")+"`n",[Text.UTF8Encoding]::new($false))
$taskQA=Get-Content "$taskProject/QA_REPORT.json" -Raw|ConvertFrom-Json
if($taskQA.latest_verified_batch.version -ne '0.15.69-dev'){throw 'Preserve previous milestone'}
$taskQA|Add-Member -NotePropertyName archived_verified_batch_0_15_69 -NotePropertyValue $taskQA.latest_verified_batch
$taskQA.latest_verified_batch=@{version='0.15.70-dev';date='2026-10-15';jar_sha256=$taskHash;jar_bytes=(Get-Item -LiteralPath $taskJar).Length;report='translation-source/NPC_0.15.70_RU.md';audit='translation-source/NPC_AUDIT_0.15.70.json';raw_performance='translation-source/PERFORMANCE_0.15.70_RAW.json';jar_entry_scope_proof='translation-source/JAR_SCOPE_0.15.70.json';packaged_gate_root=$CheckRoot;packaged_groups_passed=121;new_npc_assertions=149552;new_exact_lines=22;new_exact_speakers=15;old_literal_result_corrected=1;source_candidates_replayed=143;unchanged_before=39;unchanged_after=0;new_named_forms=2;new_Kat_time_sentence_forms=2;new_Jacob_result_forms=3;old_Jacob_collected_boundary_fixed=$true;runtime_dictionary_entries=36044;runtime_tsv_templates=1231;catalogue_compared=8937;catalogue_changed_records=0;all_frame_world_hud_f3_tooltip_dictionary_cache_classes_byte_identical=$true;new_frame_hooks=0;new_caches=0;new_network_calls=0;benchmark_root=$taskPerf.root;over10_percent_cpu_flags=$taskFlags;all_paths_faster=$false;game_fps_measured=$false;zero_fps_impact_proven=$false;all_hypixel_npcs_translated=$false;all_npc_script_denominators_known=$false;overall_goal_complete=$false;installed_modpack_modified=$false;game_started=$false}
[IO.File]::WriteAllText("$taskProject/QA_REPORT.json",($taskQA|ConvertTo-Json -Depth 40)+"`n",[Text.UTF8Encoding]::new($false))
Write-Output "NPC70 finalized:$taskHash;timing flags=$($taskFlags.Count)"
